@Bean(name = "mojaPulaWatkow")
ThreadPoolTaskExecutor mojaPulaWatkow() {
    ThreadPoolTaskExecutor executor = new ThreadPoolTaskExecutor();
    executor.setCorePoolSize(2);
    executor.setMaxPoolSize(4);
    executor.setQueueCapacity(10);
    executor.setThreadNamePrefix("moja-pula-");
    executor.initialize();
    return executor;
}

@Service
class PrzetwarzanieService {

    @Async("mojaPulaWatkow")
    public void wykonajZadanie(int numer) {
        System.out.println("Zadanie " + numer + " na watku " + Thread.currentThread().getName());
    }
}

@Service
class StatystykiService {
    public int licznik = 0; // publiczne pole

    @Async
    public void wykonaj() {
        licznik++;
    }
}

// serwis.licznik z zewnatrz -> zawsze 0, mimo wykonanych wywolan

@Service
class StatystykiService {
    private final AtomicInteger licznik = new AtomicInteger();

    @Async
    public void wykonaj() {
        licznik.incrementAndGet();
    }

    public int getLicznik() { // dostep przez metode
        return licznik.get();
    }
}
